'use strict';
const params=new URLSearchParams(location.search);
const dayKey=params.get('day');
const selectedSquad=Number(params.get('squad')??params.get('crew'))===2?2:1;
const decks={1:window.DAYS,2:window.SQUAD2};
const day=decks[selectedSquad]?.['day'+dayKey];
const slides=day?day.slides:window.TRAINING;
const $=id=>document.getElementById(id);
let current=0,phase=0,lastFocus=null,toastTimer;
const panel=$('panel');
function node(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function announce(text){$('announcement').textContent=text;}
function notify(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600);}
function openPanel(title,content){lastFocus=document.activeElement;if(lastFocus instanceof HTMLElement)lastFocus.setAttribute('aria-expanded','true');$('panel-title').textContent=title;$('panel-body').replaceChildren(content);panel.setAttribute('aria-labelledby','panel-title');panel.showModal();$('close-panel').focus();}
function closePanel(){panel.close();lastFocus?.setAttribute('aria-expanded','false');lastFocus?.focus();}
function showGlossary(){const grid=node('div','glossary-grid');(window.GLOSSARY||[]).forEach((item,i)=>{const card=node('article','glossary-item');card.style.setProperty('--i',i);card.append(node('h3',null,item.term),node('p',null,item.definition));grid.append(card);});openPanel('Glossary · return here anytime',grid);}
$('close-panel').addEventListener('click',closePanel);
panel.addEventListener('cancel',e=>{e.preventDefault();closePanel();});
$('glossary').addEventListener('click',showGlossary);
function showPrompt(custom){const s=slides[current],wrap=node('div');wrap.append(node('p','prompt-intro','Replace the bracketed context with your task. Review the scope before running the prompt.'));const area=node('textarea','prompt-text');area.value=custom||s.prompt;area.readOnly=true;area.setAttribute('aria-label','Copy-ready example prompt');wrap.append(area);const row=node('div','prompt-copy'),copy=node('button','prompt-button','Copy prompt');copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(area.value);notify('Prompt copied');copy.textContent='Copied ✓';}catch{area.focus();area.select();notify('Select and copy the prompt manually.');}});row.append(copy);const link=node('a',null,'All example prompts');link.href=day?day.guideUrl:'https://github.com/RyanLisse/claude-code-skills-pack/blob/main/examples/training-prompts.md';link.target='_blank';link.rel='noopener noreferrer';row.append(link);wrap.append(row);openPanel('Example prompts · '+s.title,wrap);}
function renderCard(c,i){const card=node('article','card');card.style.setProperty('--i',i);card.append(node('h2',null,c.title),node('p',null,c.body));return card;}
function phasePrompt(){const raw=slides[6].prompt;const name=slides[6].cards[phase].title;const re=new RegExp('(?:^|\\n\\n)'+name+'\\n([\\s\\S]*?)(?=\\n\\n(?:Plan|Design|Build|Test|Deploy|Maintain)\\n|$)','i');return raw.match(re)?.[1]||raw;}
function renderPhases(container){const tabs=node('div','phase-row');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','SDLC phases');const detail=node('div','phase-panel');detail.id='phase-detail';detail.setAttribute('role','tabpanel');slides[6].cards.forEach((c,i)=>{const btn=node('button','phase-tab',c.title);btn.id='phase-'+i;btn.setAttribute('role','tab');btn.setAttribute('aria-selected',String(i===phase));btn.setAttribute('aria-controls','phase-detail');btn.tabIndex=i===phase?0:-1;btn.addEventListener('click',()=>selectPhase(i));btn.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%6;if(e.key==='ArrowLeft')n=(i+5)%6;if(e.key==='Home')n=0;if(e.key==='End')n=5;if(n!==undefined){e.preventDefault();e.stopPropagation();selectPhase(n);$('phase-'+n).focus();}});tabs.append(btn);});container.append(tabs,detail,node('p','loop-caption','Start where the evidence points. Revisit any phase when the task changes.'));fillPhase();}
function fillPhase(){const c=slides[6].cards[phase],detail=$('phase-detail');if(!detail)return;detail.setAttribute('aria-labelledby','phase-'+phase);const title=node('div');title.append(node('div','phase-number',String(phase+1).padStart(2,'0')),node('h2',null,c.title));const body=node('div');body.append(node('p',null,c.body));const btn=node('button',null,'Use this phase prompt ↗');btn.addEventListener('click',()=>showPrompt(phasePrompt()));body.append(btn);detail.replaceChildren(title,body);}
function selectPhase(n){phase=n;document.querySelectorAll('.phase-tab').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===phase));b.tabIndex=i===phase?0:-1;});fillPhase();}

/* ---- slide layouts (pillars, steps, compare, recap, exercise timer, tagline) ---- */
let timerHandle=null;
let slideController=null;
function stopTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null;}}
function renderTagline(stage,s){if(s.tagline){stage.append(node('p','tagline',s.tagline));}}
function renderPillars(stage,s){const row=node('div','pillars');(s.items||[]).forEach((it,i)=>{const p=node('div','pillar');p.style.setProperty('--i',i);p.append(node('span','pillar-label',it.label));if(it.caption)p.append(node('span','pillar-caption',it.caption));row.append(p);});stage.append(row);}
function renderSteps(stage,s){const wrap=node('div','steps-wrap');const row=node('ol','steps-chain');let active=-1;const els=[];const co=s.callout;(s.items||[]).forEach((it,i)=>{const li=node('li','step-item');li.style.setProperty('--i',i);if(co&&co.at===i+1){const c=node('div','step-callout');c.append(node('span','step-callout-text',co.text),node('span','step-callout-arrow','▼'));li.append(c);}const b=node('button','step-btn');b.setAttribute('aria-pressed','false');b.setAttribute('aria-label','Step '+(i+1)+': '+it.label);b.append(node('span','step-circle',String(i+1)));li.append(b,node('span','step-label',it.label));if(it.caption)li.append(node('span','step-caption',it.caption));b.addEventListener('click',()=>{active=i;els.forEach((e,k)=>{e.classList.toggle('active',k===i);e.querySelector('button').setAttribute('aria-pressed',String(k===i));});cap.textContent=it.detail||it.caption||it.label;});els.push(li);row.append(li);});const cap=node('p','steps-detail',s.detail||'');const ctrl=node('div','widget-controls');const next=node('button',null,'Reveal next →');next.addEventListener('click',()=>{if(active<els.length-1){els[active+1].querySelector('button').click();}});const all=node('button','secondary','Show all');all.addEventListener('click',()=>{els.forEach(e=>{e.classList.add('active');e.querySelector('button').setAttribute('aria-pressed','true');});active=els.length-1;cap.textContent=s.detail||'';});ctrl.append(next,all);if(co&&co.at){els[co.at-1].classList.add('highlight');}wrap.append(row,cap,ctrl);stage.append(wrap);}
function renderCompare(stage,s){const grid=node('div','compare');(s.columns||[]).forEach((c,i)=>{const col=node('section','compare-col');col.style.setProperty('--i',i);col.append(node('h2',null,c.title));const ul=node('ul');(c.items||[]).forEach(x=>ul.append(node('li',null,x)));col.append(ul);if(c.foot)col.append(node('p','compare-foot',c.foot));grid.append(col);});stage.append(grid);}
function renderRecap(stage,s){const list=node('ul','recap-list');const items=s.items||[];items.forEach((it,i)=>{const li=node('li','recap-item hidden-item');li.setAttribute('aria-hidden','true');li.append(node('span','recap-check','✓'),node('span','recap-text',it.label+(it.caption?' — '+it.caption:'')));list.append(li);});let shown=0;const ctrl=node('div','widget-controls');const btn=node('button',null,'Reveal ('+items.length+')');btn.addEventListener('click',()=>{if(shown<items.length){list.children[shown].classList.remove('hidden-item');list.children[shown].removeAttribute('aria-hidden');announce(list.children[shown].textContent);shown++;btn.textContent=shown<items.length?'Reveal ('+(items.length-shown)+' left)':'All shown';}});ctrl.append(btn);stage.append(list,ctrl);}
function renderTimer(stage,s){const m=s.timer||Number((s.kicker||'').match(/(\d+)\s*MIN/i)?.[1]);if(!m)return;let left=m*60;const box=node('div','timer');const face=node('div','timer-face',String(m).padStart(2,'0')+':00');const bar=node('div','timer-bar');const fill=node('div','timer-fill');bar.append(fill);const ctrl=node('div','widget-controls');const start=node('button',null,'Start '+m+' min');const reset=node('button','secondary','Reset');function paint(){face.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');fill.style.width=(100*(1-left/(m*60)))+'%';box.classList.toggle('timer-late',left<=60);}start.addEventListener('click',()=>{if(timerHandle){stopTimer();start.textContent='Resume';announce('Timer paused');return;}start.textContent='Pause';announce('Timer started');timerHandle=setInterval(()=>{if(left>0){left--;paint();}else{stopTimer();face.textContent='TIME';notify('Time is up — individual block ends');}},1000);});reset.addEventListener('click',()=>{stopTimer();left=m*60;paint();start.textContent='Start '+m+' min';announce('Timer reset');});ctrl.append(start,reset);box.append(face,bar,ctrl);stage.append(box);}
function renderLayout(stage,s){const L=s.layout;if(L==='pillars')renderPillars(stage,s);else if(L==='steps')renderSteps(stage,s);else if(L==='compare')renderCompare(stage,s);else if(L==='recap')renderRecap(stage,s);if(s.cards?.length&&(!L||L==='exercise'||L==='cards'||s.keepCards)){const grid=node('div','cards'+(s.cards.length===3?' three':''));s.cards.forEach((c,i)=>grid.append(renderCard(c,i)));stage.append(grid);}if(L==='exercise'||(day&&L!=='recap'))renderTimer(stage,s);}
function render(){slideController?.abort();slideController=new AbortController();const s=slides[current];document.body.classList.toggle('dark',s.dark);document.title=s.title+' · AetherLink';const stage=$('stage');stage.replaceChildren();const head=node('section','heading');const top=node('div','heading-top');top.append(node('p','eyebrow',s.kicker),node('p','slide-count',String(current+1)+' / '+slides.length));head.append(top,node('h1',null,s.title),node('p','subtitle',s.subtitle));stage.append(head);{const m=node('img','mascot');m.src='assets/robot.png';m.alt='';m.setAttribute('aria-hidden','true');stage.append(m);}if(s.widget&&window.WIDGETS&&window.WIDGETS[s.widget]){stage.append(window.WIDGETS[s.widget]({signal:slideController.signal}));}stopTimer();if(day&&(s.layout||s.tagline)){renderLayout(stage,s);renderTagline(stage,s);}else if(!day&&current===6){renderPhases(stage);}else{const grid=node('div','cards'+(s.cards.length===3?' three':''));s.cards.forEach((c,i)=>grid.append(renderCard(c,i)));if(!day&&current===7){const layout=node('div','diagram-layout'),col=node('div'),zoom=node('button','diagram-button');zoom.setAttribute('aria-label','Enlarge the SDLC adoption diagram');const img=node('img');img.src='assets/adoption.png';img.alt='SDLC adoption dependencies: foundational practices connect to skills, subagents, evals, requirements, PR review, CI/CD and feedback. Readable row labels are in the adjacent legend.';zoom.append(img,node('span','zoom-label','Enlarge ↗'));zoom.addEventListener('click',()=>{const big=node('img','full-image');big.src=img.src;big.alt=img.alt;openPanel('Adoption dependencies',big);});col.append(zoom);const source=node('p','source'),link=node('a',null,'Source: Anthropic · AI-native SDLC playbook');link.href='https://claude.com/blog/the-ai-native-sdlc-playbook#sd-c2';link.target='_blank';link.rel='noopener noreferrer';source.append(link);col.append(source);layout.append(col,grid);stage.append(layout);}else stage.append(grid);}
if(day){const instructions=node('section','exercise-instructions');if(s.steps?.length){instructions.append(node('h2',null,'Do this now'));const list=node('ol');s.steps.forEach(step=>list.append(node('li',null,step)));instructions.append(list);}if(s.expected)instructions.append(node('p','expected','Expected result: '+s.expected));if(s.check)instructions.append(node('p','check','Checkpoint: '+s.check));if(instructions.childNodes.length)stage.append(instructions);}
$('count').textContent=String(current+1).padStart(2,'0')+' / '+slides.length;$('progress').style.width=((current+1)/slides.length*100)+'%';$('prev').disabled=current===0;$('next').disabled=current===slides.length-1;announce('Section '+(current+1)+' of '+slides.length+': '+s.title);}
function go(n){if(n<0||n>=slides.length)return;location.hash=String(n+1);}
function fromHash(){if(location.hash==='#stage'){$('stage').focus();return;}const n=Number(location.hash.slice(1));current=Number.isInteger(n)&&n>=1&&n<=slides.length?n-1:0;render();window.scrollTo({top:0,behavior:'instant'});}
$('prev').addEventListener('click',()=>go(current-1));$('next').addEventListener('click',()=>go(current+1));$('prompt').addEventListener('click',()=>showPrompt());$('notes').addEventListener('click',()=>openPanel('Facilitator notes · '+slides[current].title,node('div','notes-text',slides[current].notes)));
$('chapters').addEventListener('click',()=>{const list=node('nav','chapter-list');list.setAttribute('aria-label','All training sections');slides.forEach((s,i)=>{const b=node('button','chapter-link');b.append(node('span',null,String(i+1).padStart(2,'0')),node('strong',null,s.title));b.setAttribute('aria-current',String(i===current));b.addEventListener('click',()=>{closePanel();go(i);});list.append(b);});openPanel('Chapters',list);});
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{notify('Fullscreen is unavailable in this browser.');}});
document.addEventListener('fullscreenchange',()=>$('fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen'));
document.addEventListener('keydown',e=>{if(panel.open||e.altKey||e.ctrlKey||e.metaKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.closest('[role=tablist]'))return;if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();go(current+1);}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();go(current-1);}if(e.key==='Home'){e.preventDefault();go(0);}if(e.key==='End'){e.preventDefault();go(slides.length-1);}});
$('day-guide').href=day?day.guideUrl:'https://github.com/RyanLisse/aetherlink-training-template';
$('presentations').textContent=day?'Squad '+selectedSquad+' · Day '+dayKey+' · Change':'Choose session';
$('presentations').addEventListener('click',()=>{const list=node('nav','chapter-list');list.setAttribute('aria-label','Training presentations');const options=[[null,null,'Daily framework · reusable'],[1,'3','Wave 2 · Squad 1 · Day 3'],[1,'4','Wave 2 · Squad 1 · Day 4'],[1,'5','Wave 2 · Squad 1 · Day 5'],[1,'1','Squad 1 · Day 1 · Reference'],[1,'2','Squad 1 · Day 2 · Reference'],...['1','2','3','4','5'].map(key=>[2,key,'Squad 2 · New training · Day '+key])];for(const [squad,key,label] of options){const a=node('a','chapter-link',label);a.href=squad?'?squad='+squad+'&day='+key+'#1':'./#1';if((squad===selectedSquad&&key===dayKey)||(!squad&&!day))a.setAttribute('aria-current','page');list.append(a);}openPanel('Choose a presentation',list);});
window.addEventListener('pagehide',()=>{slideController?.abort();stopTimer();});
window.addEventListener('hashchange',fromHash);fromHash();
